<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$id=sanitize($_GET['id']??'');$post=null;foreach(load_json('blog.json',[]) as $candidate){if(is_array($candidate)&&($candidate['id']??'')===$id){$post=$candidate;break;}}if(!$post){http_response_code(404);fail('Post not found.');}$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$title=trim((string)($_POST['title']??''));$slug=trim((string)($_POST['slug']??''));$excerpt=trim((string)($_POST['excerpt']??''));$content=trim((string)($_POST['content']??''));$category=trim((string)($_POST['category']??'Product'));if(!$title||strlen($title)<4)$error='Add a title.';elseif(!$slug||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))$error='Use a lowercase URL slug.';elseif(!$excerpt||strlen($excerpt)<20)$error='Add a longer excerpt.';elseif(strlen(strip_tags($content))<100)$error='Add complete article content.';else{$safeContent=strip_tags($content,['p','br','strong','em','u','h1','h2','h3','blockquote','ul','ol','li','code','pre','a']);$updated=update_json('blog.json',fn($posts)=>array_map(fn($item)=>is_array($item)&&($item['id']??'')===$id?array_merge($item,['slug'=>$slug,'title'=>$title,'excerpt'=>$excerpt,'content'=>$safeContent,'category'=>$category,'featured'=>isset($_POST['featured'])]):$item,$posts));if($updated)$success='Post updated.';else$error='The post could not be saved.';}}?>
<main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a class="active" href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>Edit article</h1><small style="color:var(--subtle)"><?= e((string)$post['title']) ?></small></div><a class="button button-ghost button-small" href="<?= e(app_url('admin/blog.php')) ?>">Back</a></header><div class="admin-content"><section class="admin-card"><h2>Article content</h2><p>Update the public article and its URL.</p><form action="<?= e(app_url('admin/blog-edit.php?id='.rawurlencode($id))) ?>" method=post data-validate><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="field"><label for=title>Title</label><input id=title name=title value="<?= e((string)$post['title']) ?>" required></div><div class="field"><label for=slug>URL slug</label><input id=slug name=slug value="<?= e((string)$post['slug']) ?>" required></div><div class="field"><label for=category>Category</label><select id=category name=category><?php foreach(['Product','Development','Security','Community'] as $category):?><option value="<?= e($category) ?>" <?= ($post['category']??'Product')===$category?'selected':'' ?>><?= e($category) ?></option><?php endforeach; ?></select></div><div class="field"><label for=featured>Featured</label><select id=featured name=featured><option value=0 <?= empty($post['featured'])?'selected':'' ?>>No</option><option value=1 <?= !empty($post['featured'])?'selected':'' ?>>Yes</option></select></div><div class="field full"><label for=excerpt>Excerpt</label><textarea id=excerpt name=excerpt required><?= e((string)$post['excerpt']) ?></textarea></div><div class="field full"><label for=content>Content</label><textarea id=content name=content required><?= e((string)$post['content']) ?></textarea></div></div><?php if($error):?><div class="alert error" style="margin-top:16px"><?= e($error) ?></div><?php elseif($success):?><div class="alert success" style="margin-top:16px"><?= e($success) ?></div><?php endif;?><div class="form-submit-row"><a class="button button-ghost" href="<?= e(app_url('admin/blog.php')) ?>">Cancel</a><button class="button button-primary" type=submit>Save post <span class=arrow>↗</span></button></div></form></section></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
